// Request body
{ "name": "A", "age": 17, "email": "abc", "rollNo": 5, "subject": "Math" }

public class CreateStudentRequestDto {
    @NotBlank(message = "Name cannot be null/Empty or blank")
    @Size(min = 2, max = 50, message = "Student name must be within 2 to 50 character long")
    private String name;

    @NotNull(message = "Age is required")
    @Min(value = 18, message = "Student must be atleast 18 years old")
    private Integer age;

    @NotBlank(message = "Student email cannot be blank")
    @Email(message = "Student email must be valid")
    private String email;

    @NotNull(message = "RollNo is required")
    private Integer rollNo;

    @NotBlank(message = "Subject is required")
    private String subject;
}

// Request body
{ "id": 100, "name": "Amit", "age": 21, "email": "amit@gmail.com",
  "rollNo": 7, "subject": "Math", "deleted": true }

// CreateStudentRequestDto fields: name, age, email, rollNo, subject

private Student mapToEntity(CreateStudentRequestDto dto) {
    Student student = new Student();
    student.setName(dto.getName());
    // ... age, email, rollNo, subject
    student.setCreatedAt(LocalDateTime.now());
    student.setUpdatedAt(LocalDateTime.now());
    student.setDeleted(false);
    return student;
}
// mapToDto copies id, name, age, email, rollNo, subject, createdAt, updatedAt
// and sets message = "Student saved successfully"

